from decimal import Decimal, InvalidOperation


def _amount_is_positive(value: object) -> bool:
    """Implement NVL(TOT_AMT, 0) > 0 for the workflow guard."""
    if value is None:
        value = 0
    elif isinstance(value, str):
        if value.strip() == "":
            value = 0

    try:
        return Decimal(str(value)) > 0
    except (InvalidOperation, ValueError, TypeError):
        return False


def _account_credit_hold(record: dict, tables: dict) -> object:
    """Return CRED_HOLD from the first live matching account row."""
    account_id = record.get("ACCT_ID")
    if account_id is None:
        return ""

    for row in tables.get("ACCT_MASTER", []):
        if not isinstance(row, dict):
            continue
        if row.get("DEL_FLG") == "Y":
            continue
        if "ACCT_ID" in row and row["ACCT_ID"] == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    new_record = dict(record)
    audits = []
    notifies = []

    if state == "E" and event == "approve":
        if _amount_is_positive(record.get("TOT_AMT")):
            return {
                "state": "A",
                "record": new_record,
                "audits": ["ORD_APPR"],
                "notifies": [],
                "matched": True,
            }

    if state == "A" and event == "ship":
        return {
            "state": "S",
            "record": new_record,
            "audits": ["ORD_SHIP"],
            "notifies": ["shipped"],
            "matched": True,
        }

    if state == "S" and event == "invoice":
        return {
            "state": "I",
            "record": new_record,
            "audits": ["ORD_INV"],
            "notifies": [],
            "matched": True,
        }

    if state == "E" and event == "cancel":
        return {
            "state": "X",
            "record": new_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    if state == "A" and event == "cancel":
        if _account_credit_hold(record, tables) != "Y":
            return {
                "state": "X",
                "record": new_record,
                "audits": ["ORD_CANC"],
                "notifies": [],
                "matched": True,
            }

    if state == "I" and event == "cancel":
        return {
            "state": "X",
            "record": new_record,
            "audits": ["ORD_CANC_INV"],
            "notifies": ["credit_note"],
            "matched": True,
        }

    return {
        "state": state,
        "record": new_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
